/* Simplified illustration of the OMIGOD bug class, not OMI's real code */
struct auth { int uid; int gid; };

int handle(struct request *req) {
    struct auth a = {0};                  /* 0 is root on Linux */
    if (req->authorization != NULL) {
        if (!check_password(req->authorization, &a))
            return 401;
    }
    /* no header at all: a.uid is still 0, so this runs as root */
    return run_command(req->command, a.uid, a.gid);
}

/* Fixed: fail closed. No identity means no command. */
int handle_fixed(struct request *req) {
    struct auth a;
    if (req->authorization == NULL ||
        !check_password(req->authorization, &a))
        return 401;
    return run_command(req->command, a.uid, a.gid);
}

