    records = json.load(f)["Records"]

for r in records:
    who = r["userIdentity"].get("userName", "?")
    ip = r["sourceIPAddress"]
    new_ip = ip not in KNOWN_IPS.get(who, set())
    if new_ip and (r["eventName"] in WATCH or r.get("errorCode")):
        print(r["eventTime"][11:19], who, ip, r["eventName"],
              r.get("errorCode", "ok"))

